            // Bucket, based on the name of the test, into a "kind" which
            // generates a `foreach_*` macro below.
            let kind = match test.name.as_str() {
                s if s.starts_with("p1_cli_")
                    || s.starts_with("p2_cli_")
                    || s.starts_with("p3_cli_") =>
                {
