use std::process;
use test_programs::preview1::open_scratch_directory;

/// The bytes that the host places in `test.txt` before running this program.
/// After a rejected truncation the file must still contain exactly these bytes.
const CONTENTS: &[u8] = b"truncation test file\n";
const FILENAME: &str = "test.txt";

unsafe fn test_readonly_truncation(dir_fd: wasip1::Fd) {
    // Attempt to open the file with the truncate flag. The directory was
    // preopened with mutate permission but only read file permission, so the
    // runtime must reject the truncation rather than emptying the file.
    let result = wasip1::path_open(
        dir_fd,
        0,
        FILENAME,
        wasip1::OFLAGS_TRUNC,
        wasip1::RIGHTS_FD_READ,
        0,
        0,
    );
    assert!(
        result.is_err(),
        "truncating a read-only file must be rejected by the runtime"
    );
    if let Ok(fd) = result {
        // Defensively close it if the runtime unexpectedly handed us a
        // descriptor, so we don't leak state before the assertion above fails.
        let _ = wasip1::fd_close(fd);
    }

    // Re-open the file read-only and confirm the contents are untouched.
    let file_fd = wasip1::path_open(dir_fd, 0, FILENAME, 0, wasip1::RIGHTS_FD_READ, 0, 0)
        .expect("opening the file for reading");

    let buffer = &mut [0u8; 128];
    let nread = wasip1::fd_read(
        file_fd,
        &[wasip1::Iovec {
            buf: buffer.as_mut_ptr(),
            buf_len: buffer.len(),
        }],
    )
    .expect("reading file content");

    assert_eq!(
        &buffer[..nread],
        CONTENTS,
        "file contents must be unchanged after a rejected truncation"
    );

    wasip1::fd_close(file_fd).expect("closing the file");
}

fn main() {
    // Open the preopened read-only directory by name.
    let dir_fd = match open_scratch_directory("readonly") {
        Ok(dir_fd) => dir_fd,
        Err(err) => {
            eprintln!("{err}");
            process::exit(1)
        }
    };

    unsafe {
        test_readonly_truncation(dir_fd);
    }
}
