use std::fs;
use std::path::Path;
use wasmtime::component::{Component, Linker as CLinker, ResourceTable};
use wasmtime::{Engine, Linker, Module, Store};
use wasmtime_wasi::p1::{WasiP1Ctx, add_to_linker_async as p1_add};
use wasmtime_wasi::{DirPerms, FilePerms, WasiCtx, WasiCtxBuilder, WasiCtxView, WasiView};

const CONTENTS: &[u8] = b"truncation test file\n";

struct P2Ctx {
    wasi: WasiCtx,
    table: ResourceTable,
}
impl WasiView for P2Ctx {
    fn ctx(&mut self) -> WasiCtxView<'_> {
        WasiCtxView {
            ctx: &mut self.wasi,
            table: &mut self.table,
        }
    }
}

fn setup_dir(tag: &str) -> std::path::PathBuf {
    let dir = std::env::temp_dir().join(format!("ro_trunc_{tag}"));
    let _ = fs::remove_dir_all(&dir);
    fs::create_dir_all(&dir).unwrap();
    fs::write(dir.join("test.txt"), CONTENTS).unwrap();
    dir
}

#[tokio::main(flavor = "multi_thread")]
async fn main() -> wasmtime::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    let p1_path = &args[1];
    let p2_path = &args[2];

    // ---- p1 module ----
    {
        let dir = setup_dir("p1");
        let mut config = wasmtime::Config::new();
        config.async_support(true);
        let engine = Engine::new(&config)?;
        let mut linker = Linker::<WasiP1Ctx>::new(&engine);
        p1_add(&mut linker, |t| t)?;
        let mut builder = WasiCtxBuilder::new();
        builder.inherit_stdio();
        builder.preopened_dir(&dir, "readonly", DirPerms::READ | DirPerms::MUTATE, FilePerms::READ)?;
        let mut store = Store::new(&engine, builder.build_p1());
        let module = Module::from_file(&engine, Path::new(p1_path))?;
        let instance = linker.instantiate_async(&mut store, &module).await?;
        let start = instance.get_typed_func::<(), ()>(&mut store, "_start")?;
        start.call_async(&mut store, ()).await?;
        let after = fs::read(dir.join("test.txt")).unwrap();
        assert_eq!(after, CONTENTS, "p1: file changed!");
        println!("p1: OK, guest exited cleanly and file unchanged");
    }

    // ---- p2 component ----
    {
        let dir = setup_dir("p2");
        let mut config = wasmtime::Config::new();
        config.async_support(true);
        let engine = Engine::new(&config)?;
        let mut linker = CLinker::<P2Ctx>::new(&engine);
        wasmtime_wasi::p2::add_to_linker_async(&mut linker)?;
        let mut builder = WasiCtxBuilder::new();
        builder.inherit_stdio();
        builder.preopened_dir(&dir, "readonly", DirPerms::READ | DirPerms::MUTATE, FilePerms::READ)?;
        let ctx = P2Ctx {
            wasi: builder.build(),
            table: ResourceTable::new(),
        };
        let mut store = Store::new(&engine, ctx);
        let component = Component::from_file(&engine, Path::new(p2_path))?;
        let command =
            wasmtime_wasi::p2::bindings::Command::instantiate_async(&mut store, &component, &linker)
                .await?;
        command
            .wasi_cli_run()
            .call_run(&mut store)
            .await?
            .map_err(|()| wasmtime::format_err!("p2 run returned failure"))?;
        let after = fs::read(dir.join("test.txt")).unwrap();
        assert_eq!(after, CONTENTS, "p2: file changed!");
        println!("p2: OK, guest exited cleanly and file unchanged");
    }

    Ok(())
}
